static inline signed char CourseType() { return G<signed char>(0x005A34E0); }

void __cdecl LoadWorldAssets_re() {
    FrameImage img;
    kImageCtor(&img, 0);                                                         // 0x0043dc03
    kSurfaceCreateFull(&img, 0, 0x400, 0x320, 0, 1, 0, 0);                      // 0x0043dc24

    // building / scenery palettes (movsx + dec / je chain 0x0043dc29..0x0043dc4b: 1 Desert, 2 Tropical, 3 Links, any
    // other value Parkland), then the water palette into 0x00820740 (0x0043e83e)
    switch (CourseType()) {
    case 1: RUN(&img, kWaPalDesert); Pal(&img, 0x004CBF2C, 0x00820740); break;
    case 2: RUN(&img, kWaPalTrop);   Pal(&img, 0x004CC300, 0x00820740); break;
    case 3: RUN(&img, kWaPalLinks);  Pal(&img, 0x004CC774, 0x00820740); break;
    default: RUN(&img, kWaPalPark);  Pal(&img, 0x004CCB50, 0x00820740); break;
    }

    G<unsigned>(0x004C89A8) = 0;                                                 // 0x0043e84d
    // terrain buttons sheet (jump table 0x00442124; above 3 nothing is loaded), flag 2
    {
        static const unsigned kSheet[4] = {0x004CBF08, 0x004CBEA4, 0x004CBEC4, 0x004CBEE8};
        const unsigned t = static_cast<unsigned>(static_cast<int>(CourseType()));
        if (t <= 3)
            kLoadImage(&img, 0, kSheet[t], 0, 0, 0x100, 2);                     // 0x0043e89e
    }
    // 0x0043e8a3..0x0043e907: 13 rows of 4 buttons into the Surfaces from 0x00570cb8 (stride 0x2c, while below
    // 0x005715a8); row r: y = (r % 7) * 0x36, x from 0 (r < 7) or 0xf8 (setge / dec / and al, 8 / add 0xf8 wraps the
    // r < 7 case to 0) in steps of 0x3e; 0x3e x 0x36
    {
        unsigned dest = 0x00570CB8;
        for (int r = 0; dest < 0x005715A8; r++) {
            int x = r >= 7 ? 0xF8 : 0;
            for (int c = 0; c < 4; c++, dest += 0x2C, x += 0x3E)
                kSurfaceBlit(P(dest), 0, reinterpret_cast<int>(&img), x, (r % 7) * 0x36, 0x3E, 0x36, 1, 1);   // 0x0043e8ea
        }
    }
    // 0x0043e909..0x0043ead6: three tool-strip cells per column (jump table 0x00442134; above 3 none): x from 0x208 in
    // steps of 0x50 while below 0x2f8, into (0x00571658 + 0x2c k) - 0xb0 / + 0 / + 0xb0 at y 0 / 0x96 / 0x12c
    {
        static const short kStrip[4][6] = {
            {0x41, 0x54, 0x3E, 0x46, 0x3E, 0x58},    // 0: 0x0043e920
            {0x4B, 0x4A, 0x3E, 0x43, 0x41, 0x68},    // 1: 0x0043ea6d
            {0x48, 0x4F, 0x3E, 0x51, 0x41, 0x68},    // 2: 0x0043ea00
            {0x43, 0x54, 0x3E, 0x58, 0x43, 0x4C},    // 3: 0x0043e990
        };
        const unsigned t = static_cast<unsigned>(static_cast<int>(CourseType()));
        if (t <= 3) {
            const short* s = kStrip[t];
            unsigned d = 0x00571658;
            for (int x = 0x208; x < 0x2F8; x += 0x50, d += 0x2C) {
                kSurfaceBlit(P(d - 0xB0), 0, reinterpret_cast<int>(&img), x, 0, s[0], s[1], 1, 1);
                kSurfaceBlit(P(d), 0, reinterpret_cast<int>(&img), x, 0x96, s[2], s[3], 1, 1);
                kSurfaceBlit(P(d + 0xB0), 0, reinterpret_cast<int>(&img), x, 0x12C, s[4], s[5], 1, 1);
            }
        }
    }
    // layout sheet (jump table 0x00442144; above 3 nothing is loaded), flag 2 (0x0043eb35)
    {
        static const unsigned kLayout[4] = {0x004CBE88, 0x004CBE40, 0x004CBE58, 0x004CBE70};
        const unsigned t = static_cast<unsigned>(static_cast<int>(CourseType()));
        if (t <= 3)
            kLoadImage(&img, 0, kLayout[t], 0, 0, 0x100, 2);
    }
    // 0x0043eb3a..0x0043ebb6: ten columns of four 0x4b x 0x64 cells (x = 0x4b k), destinations esi - 0x58, esi,
    // esi - 0x2c, esi + 0x2c with esi = 0x0053dfb0 + 0xb0 k, in that order
    for (unsigned d = 0x0053DFB0, x = 0; d < 0x0053E690; d += 0xB0, x += 0x4B) {
        kSurfaceBlit(P(d - 0x58), 0, reinterpret_cast<int>(&img), x, 0, 0x4B, 0x64, 1, 1);     // 0x0043eb55
        kSurfaceBlit(P(d), 0, reinterpret_cast<int>(&img), x, 0x64, 0x4B, 0x64, 1, 1);         // 0x0043eb6c
        kSurfaceBlit(P(d - 0x2C), 0, reinterpret_cast<int>(&img), x, 0xC8, 0x4B, 0x64, 1, 1);  // 0x0043eb87
        kSurfaceBlit(P(d + 0x2C), 0, reinterpret_cast<int>(&img), x, 0x12C, 0x4B, 0x64, 1, 1); // 0x0043eba2
    }
    G<unsigned>(0x00820B6C) = 0;                                                 // 0x0043ebb8
    FreeRange(0x1B6, 0x005A9A48, 0x005A9B8C, 0x0081AC5C);                       // 0x0043ebbe..0x0043ebf1
    FreeRange(0x22E, 0x005A9C28, 0x005A9C60, 0x0081C3CC);                       // 0x0043ebf3..0x0043ec26

    // buildings and homes: four independent byte compares, each re-reading the course type
    if (CourseType() == 2) RUN(&img, kWaFlicTrop);                               // 0x0043ec28
    if (CourseType() == 1) RUN(&img, kWaFlicDesert);                             // 0x0043f10f
    if (CourseType() == 3) RUN(&img, kWaFlicLinks);                              // 0x0043f619
    if (CourseType() == 0) RUN(&img, kWaFlicPark);                               // 0x0043fb7b (test al, al)

    // scenery (jump table 0x00442154; above 3 none), each case ending in the waterfall top 0x239 (0x004409de)
    {
        const unsigned t = static_cast<unsigned>(static_cast<int>(CourseType()));
        unsigned top = 0;
        switch (t) {
        case 0: RUN(&img, kWaSwPark);   top = 0x004CA174; break;
        case 1: RUN(&img, kWaSwDesert); top = 0x004C9F50; break;
        case 2: RUN(&img, kWaSwTrop);   top = 0x004CA368; break;
        case 3: RUN(&img, kWaSwLinks);  top = 0x004C9D40; break;
        }
        if (t <= 3)
            kLoadFlic(0x239, top, 2, 0x3C, 0);
    }
    // tree palettes (0x004409e6): 1 / 2 / other, then the shared one into 0x0081d7d0 (0x00440b0f)
    {
        const signed char t = CourseType();
        if (t == 1)      { RUN(&img, kWaD1Desert); Pal(&img, 0x004C9D1C, 0x0081D7D0); }
        else if (t == 2) { RUN(&img, kWaD1Trop);   Pal(&img, 0x004C9CFC, 0x0081D7D0); }
        else             { RUN(&img, kWaD1Other);  Pal(&img, 0x004C9C48, 0x0081D7D0); }
    }
    if (CourseType() == 2) RUN(&img, kWaD2Trop);                                 // 0x00440b14
    if (CourseType() == 0) RUN(&img, kWaD2Park);                                 // 0x00440b56
    {   // flower palettes (0x00440bc7), shared one into 0x0081dae8 (0x00440d71)
        const signed char t = CourseType();
        if (t == 1)      { RUN(&img, kWaD3Desert); Pal(&img, 0x004C9A94, 0x0081DAE8); }
        else if (t == 2) { RUN(&img, kWaD3Trop);   Pal(&img, 0x004C99CC, 0x0081DAE8); }
        else             { RUN(&img, kWaD3Other);  Pal(&img, 0x004C9924, 0x0081DAE8); }
    }
    {   // tall-tree palettes (0x00440d76): Links checked twice (0x00440d7d, re-read at 0x00440de7), shared one into
        // 0x0081dc48 (0x00440f7c)
        signed char t = CourseType();
        unsigned last;
        bool links2 = false;
        if (t == 3) {
            RUN(&img, kWaD4Links);
            t = CourseType();
            links2 = t == 3;
        }
        if (links2)      { RUN(&img, kWaD4Links2); last = 0x004C9760; }
        else if (t == 1) { RUN(&img, kWaD4Desert); last = 0x004C987C; }
        else if (t == 2) { RUN(&img, kWaD4Trop);   last = 0x004C984C; }
        else             { RUN(&img, kWaD4Other);  last = 0x004C97E0; }
        Pal(&img, last, 0x0081DC48);
    }

    // object-type table (0x00440f81: dl = course type, jump table 0x00442164; above 3 untouched)
    signed char ct = CourseType();
    {
        const unsigned t = static_cast<unsigned>(static_cast<int>(ct));
        unsigned marina = 0;
        if (t <= 3) {
            for (int i = 0; i < 0x114; i++)                                      // rep movsd 0x114 dwords
                G<unsigned>(0x00578350 + 4 * i) = G<unsigned>(0x004C1A40 + 4 * i);
        }
        switch (t) {
        case 0:                                                                  // 0x004411d6
            StrCpy(0x00578530, 0x004C96CC); StrCpy(0x00578560, 0x004C9740); StrCpy(0x005786B0, 0x004C96C0);
            StrCpy(0x004C273C, 0x004C96E8); StrCpy(0x004C27C8, 0x004C96B4); StrCpy(0x004C2764, 0x004C96A4);
            marina = 0x004C969C;
            break;
        case 1:                                                                  // 0x00440f9a
            StrCpy(0x00578410, 0x004C9758); StrCpy(0x00578440, 0x004C9750); StrCpy(0x00578560, 0x004C9748);
            StrCpy(0x00578530, 0x004C9740); StrCpy(0x005785F0, 0x004C9738); StrCpy(0x00578600, 0x004C9730);
            StrCpy(0x005785C0, 0x004C9724); StrCpy(0x005785D0, 0x004C9714); StrCpy(0x00578620, 0x004C9708);
            StrCpy(0x00578630, 0x004C96FC); StrCpy(0x005786B0, 0x004C96F4);
            G<unsigned char>(0x00578432) = 1;                                    // 0x00441142
            G<unsigned char>(0x00578466) = NEG() ? 6 : 5;                                    // 0x00441149
            G<unsigned char>(0x005786D8) = 0;                                    // 0x00441150
            G<unsigned>(0x005786DC) = 0;                                         // 0x00441157
            StrCpy(0x004C273C, 0x004C96E8); StrCpy(0x004C27C8, 0x004C96E0); StrCpy(0x004C2764, 0x004C96DC);
            marina = 0x004C96D4;
            break;
        case 2:                                                                  // 0x004412cf
            StrCpy(0x00578530, 0x004C96CC); StrCpy(0x00578560, 0x004C9740); StrCpy(0x005785C0, 0x004C968C);
            StrCpy(0x005785D0, 0x004C967C); StrCpy(0x005785F0, 0x004C966C); StrCpy(0x00578600, 0x004C965C);
            StrCpy(0x00578620, 0x004C9708); StrCpy(0x00578630, 0x004C96FC); StrCpy(0x005786B0, 0x004C96C0);
            StrCpy(0x004C273C, 0x004C96E8); StrCpy(0x004C27C8, 0x004C9650); StrCpy(0x004C2764, 0x004C9644);
            marina = 0x004C969C;
            break;
        case 3:                                                                  // 0x004414a6
            StrCpy(0x00578530, 0x004C963C); StrCpy(0x00578560, 0x004C9634); StrCpy(0x005785F0, 0x004C962C);
            StrCpy(0x00578600, 0x004C9624); StrCpy(0x005785C0, 0x004C9618); StrCpy(0x005785D0, 0x004C960C);
            StrCpy(0x00578620, 0x004C9600); StrCpy(0x00578630, 0x004C95F4); StrCpy(0x004C273C, 0x004C95F0);
            StrCpy(0x004C2764, 0x004C96DC); StrCpy(0x004C27A0, 0x004C96D4); StrCpy(0x004C27C8, 0x004C95E8);
            StrCpy(0x004C2764, 0x004C95E0);
            marina = 0x004C95D8;
            break;
        }
        if (t <= 3)
            StrCpy(0x004C27A0, marina);                                          // 0x0044169d
    }
    // 0x004416bd..0x004416ca: a loop that only steps eax from 0x00578373 by 0x30 to 0x005787c3 (no memory access)
    // 0x004416cc..0x00441705: the third flic range; dl is read again after every freeTable call (0x004416e6)
    {
        int id = 0x190;
        unsigned flag = 0x0081A4F0;
        for (unsigned slot = 0x005A99B0; slot <= 0x005A9A3C; slot += 4, id++, flag += 0x32) {
            if (G<int>(slot) != -1) {
                kFreeTable(id);
                ct = CourseType();
            }
            G<int>(slot) = -1;
            G<unsigned char>(flag) = 0;
        }
    }
    // flowers and sailboats (0x00441707 on dl): 1 / 2 / 0 / other, the shared tail 0x1b3 (0x00441dea)
    {
        unsigned corner;
        if (ct == 1) { RUN(&img, kWaFDesert); corner = 0x004C932C; }
        else if (ct == 2) { RUN(&img, kWaFTrop); corner = 0x004C9070; }
        else {
            unsigned sail;
            if (ct == 0) { RUN(&img, kWaFPark);  sail = 0x004C9018; }           // 0x00441b76 test dl, dl
            else         { RUN(&img, kWaFLinks); sail = 0x004C8FB8; }
            kLoadFlic(0x1A1, sail, 8, 0x50, 1);                                  // 0x00441c0b
            RUN(&img, kWaFCommon);
            corner = 0x004C8D8C;
        }
        kLoadFlic(0x1B3, corner, 4, 0x28, 1);                                    // 0x00441dea
    }
    if (CourseType() == 2) RUN(&img, kWaGTrop);                                  // 0x00441df7
    if (CourseType() == 0) RUN(&img, kWaGPark);                                  // 0x00441e8c
    if (CourseType() == 1) RUN(&img, kWaGDesert);                                // 0x00441f1d
    {   // large trees: Links (0x00441fae, re-read at 0x00442037), Desert / Tropical (0x00442043 / 0x00442047), other;
        // the shared tail 0x197 (0x004420f3)
        signed char t = CourseType();
        unsigned big;
        bool links2 = false;
        if (t == 3) {
            RUN(&img, kWaGLinks);
            t = CourseType();
            links2 = t == 3;
        }
        if (links2)                 { RUN(&img, kWaGLinks2); big = 0x004C8A6C; }
        else if (t == 1 || t == 2)  { RUN(&img, kWaGPalmDT); big = 0x004C8AC0; }
        else                        { RUN(&img, kWaGPalm);   big = 0x004C8B14; }
        kLoadFlic(0x197, big, 4, 1, 1);
    }
    kImageDtor(&img, 0);                                                         // 0x0044210a
}

