// reset and the interface art is loaded (palettes, the 0x1e0 x 0x1e0 Surface 0x005aa778, every UI flic, the golfer
// heads found by listMatchingFiles 0x0043d2a0, bodies, tool strips and panels) into fixed global Surfaces.
